() => {
  // Find the badge element containing "问数范围"
  const all = Array.from(document.querySelectorAll('*'));
  const badge = all.find(el => el.textContent && el.textContent.includes('问数范围') && el.children.length < 10);
  if (!badge) return { found: false };
  // Walk up to find the element with indigo styling / title
  let el = badge;
  const info = [];
  for (let i=0;i<5 && el;i++){
    info.push({
      tag: el.tagName,
      cls: el.className && el.className.toString ? el.className.toString() : '',
      title: el.getAttribute ? el.getAttribute('title') : null,
      aria: el.getAttribute ? el.getAttribute('aria-label') : null,
      text: (el.textContent||'').slice(0,60)
    });
    el = el.parentElement;
  }
  return info;
}

() => {
  const all = Array.from(document.querySelectorAll('span,div,badge,[class*="badge"]'));
  const matches = all.filter(el => {
    const t = (el.textContent||'').trim();
    return t.includes('问数范围');
  });
  // sort by text length ascending to get the most specific
  matches.sort((a,b)=> (a.textContent||'').length - (b.textContent||'').length);
  return matches.slice(0,6).map(el=>({
    tag: el.tagName,
    cls: el.className ? el.className.toString() : '',
    title: el.getAttribute('title'),
    text: (el.textContent||'').replace(/\s+/g,' ').trim().slice(0,80)
  }));
}

